package com.supermercado.pos.ui;

import javax.swing.*;import com.supermercado.pos.dao.*;import com.supermercado.pos.util.*;import com.supermercado.pos.servicio.*;
public class UsuariosFrame extends JFrame {public UsuariosFrame(){super("Usuarios");UI.permiso("USUARIO_ADMIN");JPanel p=UI.panel();JTextField usuario=UI.campo(p,"Usuario nuevo");JTextField nombre=UI.campo(p,"Nombre completo");JPasswordField clave=UI.clave(p,"Contraseña");JTextField rol=UI.campo(p,"ID rol a asignar");JButton guardar=new JButton("Crear usuario");JButton ver=new JButton("Ver usuarios / roles");p.add(guardar);p.add(ver);guardar.addActionListener(e->UI.accion(this,()->{char[] pass=clave.getPassword();try{Operaciones.tx(c->{long id=Sql.insertar(c,"INSERT INTO usuario(username,password_hash,nombre_completo) VALUES(?,?,?)",usuario.getText().trim(),Seguridad.hash(pass),nombre.getText());Sql.ejecutar(c,"INSERT INTO usuario_rol(usuario_id,rol_id) VALUES(?,?)",id,Long.parseLong(rol.getText()));return null;});UI.mensaje(this,"Usuario creado");}finally{java.util.Arrays.fill(pass,'\0');}}));ver.addActionListener(e->UI.mostrar("Usuarios","SELECT id,username,nombre_completo,activo FROM usuario ORDER BY id"));add(p);pack();setLocationRelativeTo(null);}}